/// Time signatures the Engine row cycles through. Every denominator here is a
/// note value; the plugin formats have no way to read anything else.
const TIME_SIGS: &[(u16, u16)] = &[
    (4, 4),
    (3, 4),
    (2, 4),
    (2, 2),
    (5, 4),
    (6, 4),
    (7, 4),
    (3, 8),
    (5, 8),
    (6, 8),
    (7, 8),
    (9, 8),
    (11, 8),
    (12, 8),
];

/// The note the beat is counted in — the bottom number of the signature.
const UNITS: &[u16] = &[1, 2, 4, 8, 16];

/// A level as a small bar, for a menu row that is a volume: "\u{2588}\u{2588}\u{2588}\u{2591}\u{2591}".
fn level_bar(v: f32) -> String {
    const W: usize = 10;
    let filled = (v.clamp(0.0, 1.0) * W as f32).round() as usize;
    format!(
        "{}{}",
        "\u{2588}".repeat(filled),
        "\u{2591}".repeat(W - filled)
    )
}

/// How the bar is counted, for the metronome menu: "2+2+3", or the bar itself
/// when it is not grouped.
fn grouping_label(num: u16) -> String {
    let groups = choz_engine::metronome::metronome().groups();
    let sum: u16 = groups.iter().map(|g| *g as u16).sum();
    match groups.len() {
        0 => format!("{num} (even)"),
        // A grouping the signature has outgrown is shown as what it is rather
        // than as a set of accents the click is not playing.
        _ if sum != num => format!("{num} (even)"),
        _ => groups
            .iter()
            .map(|g| g.to_string())
            .collect::<Vec<_>>()
            .join("+"),
    }
}

